195	ge::graphStatus AHInfoParser::CheckMaskValid()
196	{
197	    // 1.获取变量相关参数
198	    opParamInfo_.mask.tensor = context_->GetOptionalInputTensor(MASK_INDEX);
199	    opParamInfo_.mask.desc = context_->GetOptionalInputDesc(MASK_INDEX);
200	    // 2.判断可选变量是否存在
201	    ifMask_ = 0;
202	    if (opParamInfo_.mask.tensor != nullptr) {
203	        ifMask_ = 1;
204	        // 3. 检查变量类型
205	        OP_CHECK_IF(opParamInfo_.mask.desc->GetDataType() != ge::DT_BOOL,
206	            OP_LOGE(opName_, "the mask data type only support BOOL"),
207	            return ge::GRAPH_FAILED);
208	        // 4. 检查变量Shape的Dim
209	        OP_CHECK_IF((opParamInfo_.mask.tensor->GetStorageShape().GetDimNum() != DIM_NUM_TWO),
210	            OP_LOGE(opName_, "the dim num of mask's shape should be 2"),
211	            return ge::GRAPH_FAILED);
212	        // 5.检查变量shape大小是否与input一致,mask [B,S]
213	        //  -----------------------check B Size-------------------
214	        OP_CHECK_IF((opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ZERO) != bSize_),
215	            OP_LOGE(opName_,
216	                "Input dim 1 and mask dim 0 is %u, %u respectively, they must be same.",
217	                opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ONE),
218	                opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ZERO)),
219	            return ge::GRAPH_FAILED);
220	        // -----------------------check S Size-------------------
221	        OP_CHECK_IF((opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ONE) != sSize_),
222	            OP_LOGE(opName_,
223	                "Input dim 0 and mask dim 1 is %u, %u respectively, they must be same.",
224	                opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ZERO),
225	                opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ONE)),
226	            return ge::GRAPH_FAILED);
227	    }
228	
229	    return ge::GRAPH_SUCCESS;
230	}
