379	void AHInfoParser::DumpTilingInfo(AHTilingInfo &ahInfo)
380	{
381	    OP_LOGD(context_->GetNodeName(), "seqLength:  %ld", ahInfo.sSize);
382	    OP_LOGD(context_->GetNodeName(), "batchSize:  %ld", ahInfo.bSize);
383	    OP_LOGD(context_->GetNodeName(), "hiddenSize:  %ld", ahInfo.hSize);
384	    OP_LOGD(context_->GetNodeName(), "baseH:  %ld", ahInfo.baseH);
385	    OP_LOGD(context_->GetNodeName(), "baseB:  %ld", ahInfo.baseB);
386	    OP_LOGD(context_->GetNodeName(), "baseS:  %ld", ahInfo.baseS);
387	    OP_LOGD(context_->GetNodeName(), "baseSTail:  %ld", ahInfo.baseSTail);
388	    OP_LOGD(context_->GetNodeName(), "baseHTail:  %ld", ahInfo.baseHTail);
389	    OP_LOGD(context_->GetNodeName(), "baseBTail:  %ld", ahInfo.baseBTail);
390	    OP_LOGD(context_->GetNodeName(), "baseSCnt:  %ld", ahInfo.baseSCnt);
391	    OP_LOGD(context_->GetNodeName(), "baseHCnt:  %ld", ahInfo.baseHCnt);
392	    OP_LOGD(context_->GetNodeName(), "baseBCnt:  %ld", ahInfo.baseBCnt);
393	    OP_LOGD(context_->GetNodeName(), "tilingKey:  %ld", ahInfo.tilingKey);
394	    OP_LOGD(context_->GetNodeName(), "ifMask:  %ld", ahInfo.ifMask);
395	    OP_LOGD(context_->GetNodeName(), "blockDim_:  %ld", ahInfo.blockDim);
396	}
397	
398	ge::graphStatus AHInfoParser::ParseAndCheck(AHTilingInfo &ahInfo)
399	{
400	    if (ge::GRAPH_SUCCESS != GetOpName() || ge::GRAPH_SUCCESS != GetNpuInfo()) {
401	        return ge::GRAPH_FAILED;
402	    }
403	
404	    if (ge::GRAPH_SUCCESS != CheckInputValid() || ge::GRAPH_SUCCESS != CheckWeightValid() ||
405	        ge::GRAPH_SUCCESS != CheckMaskValid() || CheckOutputValid()) {
406	        return ge::GRAPH_FAILED;
407	    }
408	
409	    if (ge::GRAPH_SUCCESS != GetTilingKey() || ge::GRAPH_SUCCESS != CoreSplit()) {
410	        return ge::GRAPH_FAILED;
411	    }
412	
413	    GenerateInfo(ahInfo);
414	    DumpTilingInfo(ahInfo);
415	
416	    return ge::GRAPH_SUCCESS;
417	}
