constexpr uint32_t OUT_DIM_3 = 3;
// Output Index
constexpr uint32_t DLIMIT = 512;
constexpr uint32_t BLIMIT = 65536;

constexpr uint32_t QK_D_PFA_MLA = 192;
constexpr uint32_t V_D_PFA_MLA = 128;

