uint32_t coreNum = CORE_INIT_NUM;  // 40 is init core num

auto platformInfoPtr = context_->GetPlatformInfo();
OP_CHECK_IF(platformInfoPtr == nullptr,
            OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(), "platformInfo is null"),
            return ge::GRAPH_FAILED);
auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);

// Prioritize socVersion from compileInfo to avoid GetCurNpuArch error on x86
auto compileInfoPtr =
    reinterpret_cast<const FlashAttentionScoreGradEnhanceCompileInfo *>(context_->GetCompileInfo());
if (compileInfoPtr != nullptr && compileInfoPtr->socVersion == platform_ascendc::SocVersion::ASCEND950) {
    npuArch = NpuArch::DAV_3510;
} else {
    npuArch = ascendcPlatform.GetCurNpuArch();
    // Fallback: if GetCurNpuArch returns invalid on x86, try compileInfo again
    if (npuArch == static_cast<NpuArch>(0xFFFF) && compileInfoPtr != nullptr) {
        if (compileInfoPtr->socVersion == platform_ascendc::SocVersion::ASCEND950) {
            npuArch = NpuArch::DAV_3510;
        }
    }
}
coreNum = ascendcPlatform.GetCoreNumAiv();
fBaseParams.coreNum = coreNum;
fBaseParams.aicNum = ascendcPlatform.GetCoreNumAic();
ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, fBaseParams.ubSize);
ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L1, fBaseParams.l1Size);
ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_A, fBaseParams.l0aSize);
ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_C, fBaseParams.l0cSize);
ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L2, fBaseParams.l2CacheSize);
OP_CHECK_IF((fBaseParams.coreNum == 0) || (fBaseParams.aicNum == 0),
            OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(),
                                        "num of coreNum(aivNum) is %lu, num of aicNum is %lu.",
                                        fBaseParams.coreNum,
                                        fBaseParams.aicNum),
            return ge::GRAPH_FAILED);

OP_CHECK_IF(fBaseParams.ubSize <= 0,
            OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(), "ubSize is invalid."),
            return ge::GRAPH_FAILED);

